{
  "problem_id": "count_submultisets_in_range",
  "nodes": [
    {
      "id": 1,
      "type": "start",
      "label": "Start",
      "next": 2
    },
    {
      "id": 2,
      "type": "process",
      "label": "Input data",
      "action": "ctx['nums'] = ctx['arg0']\nctx['l'] = ctx['arg1']\nctx['r'] = ctx['arg2']\nctx['MOD'] = 1000000007\nctx['dp'] = [1] + [0] * ctx['r']\nctx['counts'] = {}\nfor v in ctx['nums']:\n    ctx['counts'][v] = ctx['counts'].get(v, 0) + 1\nctx['valid'] = True",
      "next": 3
    },
    {
      "id": 3,
      "type": "decision",
      "label": "Valid data?",
      "logic": "ctx['valid']",
      "true_next": 4,
      "false_next": 5
    },
    {
      "id": 4,
      "type": "process",
      "label": "Process data",
      "action": "mod = ctx['MOD']\nfor val, cnt in ctx['counts'].items():\n    if val == 0:\n        mul = cnt + 1\n        for s in range(ctx['r']+1):\n            ctx['dp'][s] = (ctx['dp'][s] * mul) % mod\n    else:\n        new_dp = [0] * (ctx['r']+1)\n        for rem in range(val):\n            sum_window = 0\n            k = 0\n            for s in range(rem, ctx['r']+1, val):\n                sum_window = (sum_window + ctx['dp'][s]) % mod\n                if k > cnt:\n                    sum_window = (sum_window - ctx['dp'][ s - (cnt+1)*val ]) % mod\n                new_dp[s] = sum_window\n                k += 1\n        ctx['dp'] = new_dp",
      "next": 5
    },
    {
      "id": 5,
      "type": "process",
      "label": "Output results",
      "action": "ctx['result'] = sum(ctx['dp'][ctx['l']:ctx['r']+1]) % ctx['MOD']",
      "next": 6
    },
    {
      "id": 6,
      "type": "end",
      "label": "End",
      "output": "ctx['result']"
    }
  ]
}

