        "action": "nums = ctx['arg0']; n = len(nums); res = 0; 
for i in range(n):
    counts = [0]*(n+1)
    bit = [0]*(n+2)
    def bit_add(idx, delta):
        while idx <= n:
            bit[idx] += delta
            idx += idx & -idx
    def bit_sum(idx):
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & -idx
        return s
    def bit_find_by_order(k):
        idx = 0
        bitmask = 1 << (n.bit_length())
        while bitmask:
            t = idx + bitmask
            if t <= n and bit[t] < k:
                idx = t
                k -= bit[t]
            bitmask >>= 1
        return idx + 1
    r = 0
    for j in range(i, n):
        x = nums[j]
        if counts[x] == 0:
            counts[x] = 1
            bit_add(x, 1)
            c = bit_sum(x-1)
            pred = bit_find_by_order(c) if c > 0 else None
            total = bit_sum(n)
            succ = bit_find_by_order(c+1) if c < total else None
            delta = 0
            if pred is not None and x - pred > 1:
                delta += 1
            if succ is not None and succ - x > 1:
                delta += 1
            if pred is not None and succ is not None and succ - pred > 1:
                delta -= 1
            r += delta
        res += r

ctx['result'] = res",
