weekly-contest-362-string-transformation:
{
  "problem_id": "numberOfWays_elm",
  "functions": [{
    "name": "numberOfWays",
    "parameters": ["s","t","k"],
    "entry_node": 1,
    "nodes": [
      {
        "id": 1,
        "type": "start",
        "label": "Start",
        "bbox": {"x": 0, "y": 0, "w": 0, "h": 0},
        "next": 2
      },
      {
        "id": 2,
        "type": "process",
        "label": "Compute number of ways to transform s to t in exactly k operations",
        "action": "MOD = 1000000007
s = ctx['arg0']
t = ctx['arg1']
k = int(ctx['arg2'])
n = len(s)
if len(t) != n:
    ctx['ans'] = 0
else:
    ss = s + s
    pos = -1
    for i in range(n):
        if ss[i:i+n] == t:
            pos = i
            break
    if pos == -1:
        ctx['ans'] = 0
    else:
        lps = [0]*n
        length = 0
        i = 1
        while i < n:
            if s[i] == s[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length-1]
                else:
                    lps[i] = 0
                    i += 1
        p = n - lps[-1]
        if n % p != 0:
            p = n
        d0 = pos % p
        a = pow(n-1, k, MOD)
        sgn = 1 if k % 2 == 0 else MOD - 1
        inv_n = pow(n, MOD-2, MOD)
        if d0 == 0:
            N0 = (a + sgn * ((n-1) % MOD)) % MOD
            N0 = (N0 * inv_n) % MOD
            Nnz = (a - sgn) % MOD
            Nnz = (Nnz * inv_n) % MOD
            cnt = n // p
            ctx['ans'] = (N0 + (cnt - 1) * Nnz) % MOD
        else:
            Nnz = (a - sgn) % MOD
            Nnz = (Nnz * inv_n) % MOD
            cnt = n // p
            ctx['ans'] = (cnt * Nnz) % MOD",
        "next": 3
      },
      {
        "id": 3,
        "type": "end",
        "label": "Return the answer",
        "bbox": {"x": 0, "y": 0, "w": 0, "h": 0},
        "output": "ctx['ans']"
      }
    ]
  }],
  "nodes": []
}

