          "action": "ctx['word'] = ctx['arg0']; ctx['k'] = ctx['arg1']; ctx['n'] = len(ctx['word']); ctx['ans'] = 0",
          "next": 3
        },
        {
          "id": 3,
          "type": "process",
          "label": "Compute ord values",
          "action": "ctx['arr'] = [ord(ch) - 97 for ch in ctx['word']]",
          "next": 4
        },
        {
          "id": 4,
          "type": "process",
          "label": "Build prefix sums of letter counts",
          "action": "ctx['pref'] = [[0]*26 for _ in range(ctx['n']+1)];\nfor i in range(ctx['n']):\n    ctx['pref'][i+1] = ctx['pref'][i][:]\n    ctx['pref'][i+1][ctx['arr'][i]] += 1",
          "next": 5
        },
        {
          "id": 5,
          "type": "process",
          "label": "Count valid substrings within blocks",
          "action": "n = ctx['n']; word = ctx['word']; k = ctx['k']; pref = ctx['pref']; arr = ctx['arr']; ans = 0; i = 0; while i < n:\n    j = i\n    while j+1 < n and abs(arr[j] - arr[j+1]) <= 2:\n        j += 1\n    for L in range(i, j+1):\n        max_m = (j - L + 1) // k\n        if max_m > 26:\n            max_m = 26\n        for m in range(1, max_m+1):\n            R = L + k*m\n            ok = True\n            for c in range(26):\n                cnt = pref[R][c] - pref[L][c]\n                if cnt != 0 and cnt != k:\n                    ok = False\n                    break\n            if ok:\n                ans += 1\n    i = j + 1\nctx['ans'] = ans",
          "next": 6
        },
        {
          "id": 6,
          "type": "return",
